      const updatedCard = await db.query('SELECT * FROM cards WHERE id = $1', [card.id]);

      // Broadcast the event to all SSE clients
      broadcastEvent('cardMoved', {
        card: updatedCard.rows[0],
        oldColumnId: card.column_id
      });

