      'UPDATE cards SET position = $1 WHERE id = $2',
      [i, cards.rows[i].id]
    );
  }

  // Broadcast the renormalization event
  broadcastEvent('positionsRenormalized', { columnId, cards: cards.rows });
}

// Start server
const PORT = 3000;
initDB().then(() => {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
});"}

